const edition = globalThis.makeSubjectEdition({"year":2020,"grade":"7-8","tasksFile":"ZR_1920_quest_Standard_7-8.pdf","answersFile":"reviewed-7-8.pdf","title":"Эрмитаж","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":45,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2020/7-8.json","sections":[{"start":1,"title":"История"},{"start":16,"title":"Коллекция"},{"start":31,"title":"Деятельность"}],"reviewedKey":true}, [{"title":"Первый директор музея","question":"Кто стал первым директором Императорского Эрмитажа после учреждения этой должности в 60-х годах XIX века?","choices":["М. И. Артамонов","А. А. Васильчиков","С. А. Гедеонов","М. Б. Пиотровский"],"answer":2,"steps":["Степан Гедеонов занимался археологией и музейным делом.","Он возглавил Императорский Эрмитаж, когда появилась отдельная должность директора."]},{"title":"Школа реставраторов","question":"Первая в России реставраторская школа возникла в Эрмитаже по инициативе…","choices":["А. Ф. Митрохина","Ф. И. Лабенского","Ф. П. Толстого","Г. Х. Гроота"],"answer":1,"steps":["Франц Лабенский руководил картинной галереей и следил за состоянием собрания.","С его деятельностью связано обучение мастеров, восстанавливавших картины."]},{"title":"Как увидеть скрытое","question":"Для систематического исследования структуры памятников в 1936 году в Эрмитаже была открыта первая в стране …","choices":["архитектурная лаборатория","химическая лаборатория","рентгеновская лаборатория","стекольная лаборатория"],"answer":2,"steps":["Рентгеновские лучи показывают слои и детали, которые на поверхности не видны.","Лаборатория Эрмитажа изучала таким способом строение памятников и прежние изменения."]},{"title":"Испанская живопись","question":"При этом императоре в Эрмитаж поступила первая большая партия испанских картин.","choices":["Александр I","Николай I","Екатерина II","Павел I"],"answer":0,"steps":["В царствование Александра I Эрмитаж приобрёл многочисленные работы испанских мастеров.","Среди ранних крупных покупок были картины из собрания Кузвельта."]},{"title":"Поступление сокровищ","question":"Уникальная коллекция сокровищ великих моголов поступила в Зимний дворец во время правления …","choices":["Анны Иоанновны","Анны Леопольдовны","Елизаветы Петровны","Екатерины II"],"answer":1,"steps":["Индийские драгоценности попали в Петербург в составе дипломатических даров.","Это произошло во время регентства Анны Леопольдовны при младенце Иване VI."]},{"title":"Первая распродажа","question":"Первая распродажа экспонатов эрмитажной коллекции была осуществлена по указу …","choices":["Николая I","Николая II","В. И. Ленина","И. В. Сталина"],"answer":0,"steps":["Николай I распорядился продать часть картин после пересмотра экспозиции.","Эта распродажа середины XIX века предшествовала гораздо более масштабным продажам 1920–1930-х годов."]},{"title":"Проект для кадетов","question":"Этот архитектор получил звание академика за проект по перестройке Меншиковского дворца для Шляхетского кадетского корпуса.","choices":["Ф. Б. Растрелли","И. Е. Старов","В. П. Стасов","К. Росси"],"answer":1,"steps":["Иван Старов разработал проект приспособления Меншиковского дворца для Шляхетского корпуса.","Работа над проектом принесла ему звание академика."]},{"title":"Планы для зала","question":"В этом зале Нового Эрмитажа по проекту Л. фон Кленце должна была расположиться библиотека иностранной литературы.","choices":["Зал Диониса","Зал Юпитера","Зал Геракла","Зал Августа"],"answer":2,"steps":["Лео фон Кленце задумывал библиотеку в помещении, которое позднее стало залом Геракла.","Сейчас в зале показывают античные скульптуры."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/8.webp","alt":"Длинный зал со сводами и статуями","width":209,"height":141}},{"title":"Покои императорской четы","question":"Этим архитектором были спроектированы личные апартаменты императора Александра I и его супруги в Зимнем дворце в стиле ампир.","choices":["К. Росси","В. П. Саров","Л. Руска","О. Монферран"],"answer":2,"steps":["Луиджи Руска проектировал дворцовые интерьеры с античными мотивами, характерными для ампира.","В Зимнем дворце с ним связаны покои Александра I и его супруги."]},{"title":"Надпись на окне","question":"На стекле окна музыкального салона Зимнего дворца сохранилась надпись: «Ники 1902 смотрит на гусар 17 марта», сделанная императрицей …","choices":["Александрой Фёдоровной","Марией Александровной","Елизаветой Алексеевной","Анной Иоанновной"],"answer":0,"steps":["Словом «Ники» Александра Фёдоровна называла супруга Николая II.","Она оставила датированную надпись, пока император смотрел на проходивших гусар."]},{"title":"Зал к свадьбе","question":"Этот зал Зимнего дворца был создан А. П. Брюлловым к свадьбе будущего императора Александра II.","choices":["Гербовый","Белый","Георгиевский","Александровский"],"answer":1,"steps":["Брюллов отделал Белый зал к свадьбе наследника Александра Николаевича и Марии Александровны.","Светлое оформление и регулярный ритм колонн подчёркивают торжественность."]},{"title":"Оформление фойе","question":"Оформление фойе Эрмитажного театра в стиле неорококо было связано с…","choices":["переустройством театра","постановкой балетов С. П. Дягилева","установкой подарка правительства Франции","визитом персидского шаха"],"answer":2,"steps":["Французский подарок нужно было разместить в пространстве театра.","При новом оформлении фойе использовали мотивы рококо."]},{"title":"След государственного совета","question":"Эта лестница Старого Эрмитажа получила своё название благодаря тому, что в здании в XIX веке размещались помещения высшего законосовещательного учреждения.","choices":["Посольская","Октябрьская","Советская","Церковная"],"answer":2,"steps":["В Большом Эрмитаже размещались помещения Государственного совета.","Название Советской лестницы связано с этим учреждением."]},{"title":"Игровой штраф","question":"Каждый, кто нарушил эрмитажный этикет Екатерины II, должен был прочитать стихи…","choices":["В. К. Тредиаковского","А. П. Сумарокова","Г. Р Державина","М. В. Ломоносова"],"answer":0,"steps":["При императорских собраниях правила запрещали спорить и важничать.","Среди шутливых наказаний упоминалось чтение стихов Василия Тредиаковского."]},{"title":"Зодчий из Европы","question":"Первый архитектор Меншиковского дворца был родом из…","choices":["Германии","Франции","Швейцарии","Голландии"],"answer":2,"steps":["К ранним архитекторам дворца относится Джованни Мария Фонтана.","Он происходил из италоязычной части нынешней Швейцарии."]},{"title":"Запись об охоте","question":"Надпись об охоте Аменхотепа III на диких львов выполнена на поверхности этого эрмитажного артефакта.","choices":["Папирусный свиток","Каменный саркофаг","Статуэтка скарабея","Бронзовый кинжал"],"answer":2,"steps":["В Египте на крупных памятных скарабеях вырезали надписи о событиях правления царя.","Один из таких предметов сообщает об охоте Аменхотепа III на львов."]},{"title":"Два профильных портрета","question":"Кого, по атрибуции Государственного Эрмитажа, изображают два профильных портрета на камее Гонзага?","choices":["Птолемея X и Беренику III","Птолемея I и Эвридику I","Птолемея V и Клеопатру I","Птолемея II и Арсиною II"],"answer":3,"steps":["Эрмитаж идентифицирует портреты как египетского царя Птолемея II и царицу Арсиною II. Их профили вырезаны на разных слоях сардоникса.","Существуют и другие научные версии о том, кто изображён на камее. Формулировка вопроса относится к атрибуции Эрмитажа."],"references":["https://www.hermitagemuseum.org/explore/collections/category_4/element_68","https://journals.ub.uni-heidelberg.de/index.php/bjb/article/download/82061/76236"],"taskUrl":"https://runodog.ru/ZR_1920/ZR_1920_quest_Standard_7-8.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2020/lessons/7-8/17.webp","alt":"Камея с двумя профильными портретами","width":142,"height":175}},{"title":"Экспонат на гербе","question":"Этот эрмитажный экспонат изображён на гербе Алтайского края.","choices":["Ваза Фортуни","Чингисов камень","Колыванская ваза","Ваза «Большой урожай винограда»"],"answer":2,"steps":["На гербе Алтайского края показана знаменитая ваза, созданная на местной гранильной фабрике.","Именно место изготовления связывает Колыванскую вазу с Алтаем."]},{"title":"Надгробие и поэт","question":"В создании этого шедевра русского барокко, хранящегося в Эрмитаже, принял участие…","choices":["М. В. Ломоносов","Ф. Б. Растрелли","А. К. Нартов","К. Б. Растрелли"],"answer":0,"steps":["Для серебряного надгробия Александра Невского составили стихотворные надписи.","Над текстом работал Михаил Ломоносов, поэтому его вклад относится к оформлению памятника."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/19.webp","alt":"Серебряная композиция с рельефами и фигурами в дворцовом зале","width":141,"height":138}},{"title":"Миф на заказ","question":"Эта картина была создана по заказу Екатерины II.","choices":["«Капризница» А. Ватто","«Младенец Геракл, удушающий змей» Дж. Рейнолдса","Портрет Вольтера в кресле Ж.-А. Гудона","«Поцелуй украдкой» Ж.-А. Фрагонара"],"answer":1,"steps":["Екатерина II заказала Рейнольдсу картину, допускавшую аллегорию могущества России.","Художник показал, как младенец Геракл справляется со змеями."]},{"title":"Ювелирный подарок","question":"Лилии из жемчужин и бриллиантов, находящиеся в Галерее драгоценностей Эрмитажа, выполнены в качестве подарка к свадьбе великой княжны Александры Павловны в мастерской…","choices":["Фаберже","Ж. Позье","Дювалей","РЛалика"],"answer":2,"steps":["Дювали работали для российского двора и выполняли изделия с драгоценными камнями.","Свадебный подарок Александре Павловне выполнен в виде лилий из жемчуга и бриллиантов."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/21.webp","alt":"Изящный металлический цветок на подставке","width":101,"height":168}},{"title":"Шали из мастерских","question":"Эти предметы русского прикладного искусства начала XIX века, экспонируемые в Эрмитаже, получили название «колокольцевские» в честь владельцев мастерских, в которых они были изготовлены.","choices":["Шали","Керамика","Шкатулки","Игрушки"],"answer":0,"steps":["Шерстяные шали ценили за сложный орнамент и тонкое ткачество.","Колокольцевские шали называли по фамилии владельцев мастерских."]},{"title":"Фигура для капеллы","question":"Эту скульптуру Микеланджело создал для украшения Капеллы герцогов Медичи.","choices":["«Пьета»","«Ангел с канделябром»","«Бахус»","«Скорчившийся мальчик»"],"answer":3,"steps":["Микеланджело создавал для капеллы Медичи мраморные фигуры разного масштаба.","С проектом связывают небольшую скульптуру мальчика, который согнулся и обхватил ногу."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/23.webp","alt":"Мраморная фигура сидящего юноши","width":116,"height":145}},{"title":"Перенос живописи","question":"Эта эрмитажная картина была переведена реставраторами с дерева на холст.","choices":["«Мадонна со святыми» фра Беато Анджелико","«Святой Себастьян» Дж. Больтраффио","«Лютнист» Караваджо","«Юдифь» Джорджоне"],"answer":3,"steps":["«Юдифь» Джорджоне была написана на деревянной основе.","При реставрации красочный слой перенесли на холст."]},{"title":"Автор скульптурной группы","question":"Что известно об авторстве мраморной группы «Мёртвый мальчик на дельфине» из коллекции Государственного Эрмитажа?","choices":["Скульптуру подписал Микеланджело","В договоре указан Пьетро Перуджино","Авторство остаётся предметом исследования","Сохранилось письмо Бенвенуто Челлини о её создании"],"answer":2,"steps":["В разное время скульптуру связывали с Лоренцетто и Джулио Чезаре Конвенти. Специалисты сравнивали её с другими произведениями этих мастеров.","Документального подтверждения авторства нет. Оно остаётся предметом исследования."],"references":["https://www.hermitagemuseum.org/uploads/files/file_i8fyr5h23t7r51ruy238rj16_ca216130e73c64f9d0338f944caf9409.pdf","https://en.peterhofmuseum.ru/assets/files/20190710/0ef6b92c62206165ba13641b8510ca9f.pdf"],"taskUrl":"https://runodog.ru/ZR_1920/ZR_1920_quest_Standard_7-8.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2020/lessons/7-8/25.webp","alt":"Мраморная фигура юноши на дельфине","width":173,"height":115}},{"title":"Картина из собрания Кроза","question":"Эта картина Рафаэля попала в Эрмитаж с приобретённой в 1772 году коллекцией семьи Кроза.","choices":["«Преображение»","«Мадонна с безбородым Иосифом»","«Донна Велата»","«Мадонна с рыбой»"],"answer":1,"steps":["Коллекция Кроза поступила в Эрмитаж при Екатерине II.","Среди её произведений была картина Рафаэля со Святым семейством, на которой Иосиф изображён без бороды."]},{"title":"Примета мифа","question":"Отсутствие этой детали на картине позволяло искусствоведам предполагать, что на ней изображена не Даная, а другой мифологический персонаж.","choices":["Золотой дождь","Золотое облако","Стрелы Купидона","Молнии Зевса"],"answer":0,"steps":["По мифу Зевс проник к Данае в виде золотого дождя.","На картине Рембрандта такой дождь не показан, что породило сомнения в сюжете."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/27.webp","alt":"Фигуры на ложе в освещённой комнате","width":171,"height":154}},{"title":"Предметы художественного труда","question":"Эта эрмитажная картина была написана специально для Петербургской академии художеств.","choices":["«Художники» Г. Робера","«Натюрморт с атрибутами искусств» Ж.-Б. Шардена","«Амур, удушающий змей» Дж. Рейнолдса","Портрет Вольтера в кресле Ж.-А. Гудона"],"answer":1,"steps":["Шарден изобразил вещи, связанные с живописью и другими искусствами.","Натюрморт с этими атрибутами был предназначен для Петербургской академии художеств."]},{"title":"Пир бобового короля","question":"Этот праздник Я. Йорданс запечатлел на картине «Бобовый король».","choices":["Новый год","День защиты детей","День трёх волхвов","День Европы"],"answer":2,"steps":["При праздновании Богоявления, или Дня трёх волхвов, боб прятали в пироге.","Нашедший его становился королём пиршества, которое и написал Йорданс."],"figure":{"src":"assets/golden-fleece/2020/lessons/5-6/23.webp","alt":"Праздничная компания за столом","width":560,"height":427,"detailSrc":"assets/golden-fleece/2020/lessons/5-6/23-detail.webp"}},{"title":"Возвращение знамени","question":"Георгиевское знамя лейб-гвардии Гренадерского полка поступило в Эрмитаж в 2003 году из…","choices":["США","Франции","Великобритании","Италии"],"answer":2,"steps":["Полковое знамя сохранялось за рубежом после перемен XX века.","В 2003 году оно поступило в музей из Великобритании."]},{"title":"День музея","question":"Официальный петербургский праздник День Эрмитажа ежегодно отмечается в День …","choices":["музеев","святого Петра","святой Екатерины","художника"],"answer":2,"steps":["День Эрмитажа приходится на 7 декабря, день памяти святой Екатерины.","Дата напоминает и о Екатерине II, с которой связано основание собрания."]},{"title":"Бывшее министерство","question":"В этом подразделении Эрмитажа находятся помещения бывшего Министерства иностранных дел Российской империи.","choices":["Отдел истории и реставрации памятников архитектуры","Отдел истории русской культуры","Отдел организации учета и хранения РХЦ «Старая Деревня»","Главный штаб"],"answer":3,"steps":["Часть пространства Главного штаба занимали имперские министерства.","В музейных залах сохранились помещения Министерства иностранных дел."]},{"title":"Залы для концертов","question":"В этом зале Эрмитажа проводятся концерты симфонической музыки.","choices":["Романовская галерея","Итальянские просветы","Малахитовый зал","Шатровый зал"],"answer":1,"steps":["Итальянские просветы представляют собой высокие музейные пространства с верхним светом.","Там проводят концерты симфонической музыки."]},{"title":"Международная программа","question":"Программа «Соединяя музеи» позволила Эрмитажу создавать совместные проекты с этим музеем.","choices":["ГМИИ им. А. С. Пушкина","Государственный Русский музей","Музей С. Р. Гуггенхайма","Лувр"],"answer":2,"steps":["Проект «Соединяя музеи» строился на сотрудничестве больших музейных собраний.","Среди партнёрских учреждений был Музей Соломона Гуггенхайма."]},{"title":"Описание сложного переноса","question":"Этот очерк В. В. Стасова —- важнейшее документальное свидетельство процесса перевода картины с доски на холст в реставрационной мастерской Эрмитажа.","choices":["«Нужно ли образование художнику»","«Чудо чудесное»","«Наши художественные дела»","«Художественная хирургия»"],"answer":3,"steps":["Стасов наблюдал реставрацию, при которой живописный слой отделяли от повреждённой основы.","Очерк «Художественная хирургия» описывает работу как последовательность операций."]},{"title":"Европейский выставочный центр","question":"В какой европейской столице в год проведения конкурса, в 2020 году, работал выставочный центр Государственного Эрмитажа?","choices":["Париж","Амстердам","Лондон","Берлин"],"answer":1,"steps":["В Амстердаме проекты Эрмитажа показывали в здании на реке Амстел.","Этот факт относится ко времени выпуска буклета в 2020 году."],"adaptation":"В вопросе указан год проведения конкурса."},{"title":"Как определяют авторство","question":"В результате этой деятельности было установлено авторство Р. Кампена данной эрмитажной картины.","choices":["Консервация","Экспозиция","Атрибуция","Реставрация"],"answer":2,"steps":["При атрибуции исследуют материалы, технику, историю владения и сходство с другими работами.","Так эрмитажную картину связали с Робером Кампеном."],"figure":{"src":"assets/golden-fleece/2020/lessons/7-8/37.webp","alt":"Женщина в синем и красном с книгой","width":137,"height":213}},{"title":"Работы во дворцовом комплексе","question":"При реконструкции этого комплекса архитектурно-археологическая экспедиция Эрмитажа проводила специальные исследования.","choices":["Охта-центр","Константиновский дворец","Аржан-2","Старая Ладога"],"answer":1,"steps":["Прежде чем восстанавливать Константиновский дворец в Стрельне, исследовали ранние строительные слои.","В этой работе участвовала экспедиция Эрмитажа."]},{"title":"Выставки в Лондоне","question":"Выставочные залы в этом здании были стилизованы под интерьеры Нового Эрмитажа.","choices":["Амстелхоф","Панцерлакс","Старые прокурации","Сомерсет-Хаус"],"answer":3,"steps":["В лондонском Сомерсет-хаусе действовало выставочное пространство Эрмитажа.","Его залы оформляли с оглядкой на интерьеры Нового Эрмитажа."]},{"title":"Современный художник","question":"В рамках проекта «Эрмитаж 20/21» в музее открылся зал этого современного художника.","choices":["Т. П. Новиков","А. Кифер","Л. Буржуа","Д. А. Пригов"],"answer":3,"steps":["Дмитрий Пригов соединял рисунок, текст и инсталляцию.","Его работы вошли в программу «Эрмитаж 20/21», посвящённую современному искусству."]},{"title":"Премьера оратории","question":"В рамках этого культурного проекта в Эрмитаже состоялась российская премьера оратории К. Пендерецкого «Семь врат Иерусалима».","choices":["«Соединяя музеи»","«Эрмитаж 20/21»","«Tuba mirum»","«Дворцы Санкт-Петербурга»"],"answer":2,"steps":["Пендерецкий создал ораторию на образы семи врат Иерусалима.","Российскую премьеру в Эрмитаже организовали в рамках музыкального проекта «Tuba mirum»."]},{"title":"Исследование находки","question":"Эрмитаж — обладатель премии «Олимпия» за находку, реставрацию и исследование объекта из…","choices":["Остии","Ольвии","Нимфея","Никеи"],"answer":2,"steps":["Античный Нимфей находился на Керченском полуострове.","Исследование, реставрация и представление находки из этого места принесли музею премию."]},{"title":"Возвращение в инсталляции","question":"Назовите создателя инсталляции на тему рембрандтовского «Возвращения блудного сына» для Венецианской биеннале 2019 года.","choices":["М. М. Шемякин","А. Н. Сокуров","А. Шишкин-Хокусай","М. Б. Пиотровский"],"answer":1,"steps":["Александр Сокуров обратился к картине Рембрандта как к сцене встречи отца и сына.","Инсталляция представила работу в новом пространстве Венецианской биеннале."]},{"title":"Один дубль в музее","question":"Действие этого фильма А. Н. Сокурова, снятого за один дубль, происходит в интерьерах Эрмитажа.","choices":["«Фауст»","«Русский ковчег»","«Солнце»","«Отец и сын»"],"answer":1,"steps":["В «Русском ковчеге» камера переходит из зала в зал, не прерывая съёмку.","Встреча людей разных эпох превращает Эрмитаж в пространство исторического путешествия."]},{"title":"Буква на знаке","question":"Этому художнику, создателю логотипа Эрмитажа, музей посвятил выставку под названием «Кто придумал букву «Э»?».","choices":["А. И. Кузьминский","Ю. Л. Купер","Д. А. Пригов","М. М. Шемякин"],"answer":0,"steps":["Для знака музея художник Александр Кузьминский использовал выразительную букву «Э».","Выставка объяснила историю этой графической работы и её автора."]}]);
